import { useState, type ChangeEvent } from 'react';
import { Button, Card, Input, Stack, Text } from '@jinx-ui/react';

type RegistrationData = {
  name: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  zip: string;
};

type RegistrationWizardProps = {
  onSubmit: (data: RegistrationData) => void;
};

const STEPS = ['Контакты', 'Адрес', 'Проверка'] as const;

const EMPTY: RegistrationData = {
  name: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  zip: '',
};

const SUMMARY: ReadonlyArray<readonly [string, keyof RegistrationData]> = [
  ['Имя', 'name'],
  ['Email', 'email'],
  ['Телефон', 'phone'],
  ['Страна', 'country'],
  ['Город', 'city'],
  ['Улица', 'street'],
  ['Индекс', 'zip'],
];

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>(EMPTY);

  const isFirst = step === 0;
  const isLast = step === STEPS.length - 1;

  const update =
    (field: keyof RegistrationData) => (event: ChangeEvent<HTMLInputElement>) =>
      setData((prev) => ({ ...prev, [field]: event.target.value }));

  const handleNext = () => {
    if (isLast) {
      onSubmit(data);
      return;
    }
    setStep((prev) => prev + 1);
  };

  return (
    <Card>
      <Stack direction="column" gap="lg">
        <Stack direction="row" gap="md" align="center">
          {STEPS.map((label, index) => (
            <Stack
              key={label}
              direction="row"
              gap="xs"
              align="center"
              aria-current={index === step ? 'step' : undefined}
            >
              <span
                aria-hidden="true"
                style={{
                  display: 'inline-flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  width: 'var(--jx-size-6)',
                  height: 'var(--jx-size-6)',
                  borderRadius: 'var(--jx-radius-full)',
                  background:
                    index <= step
                      ? 'var(--jx-color-primary)'
                      : 'var(--jx-color-surface-muted)',
                  color:
                    index <= step
                      ? 'var(--jx-color-on-primary)'
                      : 'var(--jx-color-text-muted)',
                }}
              >
                {index + 1}
              </span>
              <Text tone={index === step ? 'default' : 'muted'}>{label}</Text>
            </Stack>
          ))}
        </Stack>

        {step === 0 && (
          <Stack direction="column" gap="md">
            <Input label="Имя" value={data.name} onChange={update('name')} />
            <Input
              label="Email"
              type="email"
              value={data.email}
              onChange={update('email')}
            />
            <Input
              label="Телефон"
              type="tel"
              value={data.phone}
              onChange={update('phone')}
            />
          </Stack>
        )}

        {step === 1 && (
          <Stack direction="column" gap="md">
            <Input label="Страна" value={data.country} onChange={update('country')} />
            <Input label="Город" value={data.city} onChange={update('city')} />
            <Input label="Улица" value={data.street} onChange={update('street')} />
            <Input label="Индекс" value={data.zip} onChange={update('zip')} />
          </Stack>
        )}

        {step === 2 && (
          <Stack direction="column" gap="sm">
            {SUMMARY.map(([label, field]) => (
              <Stack key={field} direction="row" gap="sm" justify="space-between">
                <Text tone="muted">{label}</Text>
                <Text>{data[field] || '—'}</Text>
              </Stack>
            ))}
          </Stack>
        )}

        <Stack direction="row" gap="sm" justify="flex-end">
          <Button variant="secondary" disabled={isFirst} onClick={() => setStep((prev) => prev - 1)}>
            Назад
          </Button>
          <Button variant="primary" onClick={handleNext}>
            {isLast ? 'Отправить' : 'Дальше'}
          </Button>
        </Stack>
      </Stack>
    </Card>
  );
}

